const getSurgeryStatistics = `-- name: GetSurgeryStatistics :one
SELECT 
    COUNT(DISTINCT patient_id) as patients_with_surgeries,
    COUNT(*) as total_surgeries,
    COUNT(*) FILTER (WHERE outcome = 'successful') as successful_surgeries,
    COUNT(*) FILTER (WHERE complications IS NOT NULL) as surgeries_with_complications,
    COUNT(DISTINCT procedure_name) as unique_procedures,
    COUNT(DISTINCT hospital_name) as hospitals_used,
    AVG(EXTRACT(YEAR FROM AGE(CURRENT_DATE, procedure_date))) FILTER (WHERE procedure_date IS NOT NULL) as avg_years_since_surgery
FROM patient_surgeries
`

type GetSurgeryStatisticsRow struct {
	PatientsWithSurgeries      int64   `json:"patients_with_surgeries"`
	TotalSurgeries             int64   `json:"total_surgeries"`
	SuccessfulSurgeries        int64   `json:"successful_surgeries"`
	SurgeriesWithComplications int64   `json:"surgeries_with_complications"`
	UniqueProcedures           int64   `json:"unique_procedures"`
	HospitalsUsed              int64   `json:"hospitals_used"`
	AvgYearsSinceSurgery       float64 `json:"avg_years_since_surgery"`
}

func (q *Queries) GetSurgeryStatistics(ctx context.Context) (GetSurgeryStatisticsRow, error) {
	row := q.db.QueryRow(ctx, getSurgeryStatistics)
	var i GetSurgeryStatisticsRow
	err := row.Scan(
		&i.PatientsWithSurgeries,
		&i.TotalSurgeries,
		&i.SuccessfulSurgeries,
		&i.SurgeriesWithComplications,
		&i.UniqueProcedures,
		&i.HospitalsUsed,
		&i.AvgYearsSinceSurgery,
	)
	return i, err
}

const getSurgeryTrends = `-- name: GetSurgeryTrends :many
SELECT 
    DATE_TRUNC('year', procedure_date) as year,
    COUNT(*) as surgery_count,
    COUNT(DISTINCT patient_id) as unique_patients,
    COUNT(DISTINCT procedure_name) as unique_procedures
FROM patient_surgeries
WHERE procedure_date >= $1
GROUP BY DATE_TRUNC('year', procedure_date)
ORDER BY year DESC
`

type GetSurgeryTrendsRow struct {
	Year             pgtype.Interval `json:"year"`
	SurgeryCount     int64           `json:"surgery_count"`
	UniquePatients   int64           `json:"unique_patients"`
	UniqueProcedures int64           `json:"unique_procedures"`
}

